import 'package:flutter/foundation.dart'; import '../../data/dto/batch_delete_result.dart'; import '../../domain/entities/competition.dart'; import '../../domain/repositories/competition_repository.dart'; import '../../domain/usecases/competition_usecases.dart'; class CompetitionListController extends ChangeNotifier { CompetitionListController(this._useCases); final CompetitionUseCases _useCases; List<Competition> _items=const []; Set<String> _selectedIds=<String>{}; bool _isLoading=false; bool _isSaving=false; String? _errorMessage; int _page=0; int _totalPages=0; String _search=''; List<Competition> get items=>List.unmodifiable(_items); Set<String> get selectedIds=>Set.unmodifiable(_selectedIds); bool get isLoading=>_isLoading; bool get isSaving=>_isSaving; String? get errorMessage=>_errorMessage; int get page=>_page; int get totalPages=>_totalPages; bool get hasNextPage=>_page+1<_totalPages; bool get hasPreviousPage=>_page>0; Future<void> load({int? page,String? search}) async { if(_isLoading)return; if(page!=null)_page=page; if(search!=null)_search=search; _isLoading=true; _errorMessage=null; notifyListeners(); try{final PagedCompetitionResult r=await _useCases.list(page:_page,search:_search.isEmpty?null:_search); _items=r.competitions; _page=r.page; _totalPages=r.totalPages; _selectedIds.removeWhere((id)=>!_items.any((e)=>e.id==id));}catch(_){_errorMessage='No se pudieron cargar las competiciones.';}finally{_isLoading=false;notifyListeners();}} void toggleSelection(String id){_selectedIds.contains(id)?_selectedIds.remove(id):_selectedIds.add(id);notifyListeners();} Future<bool> create({required String name,required String description})=>_run(()=>_useCases.create(name:name,description:description)); Future<bool> update({required String id,required String name,required String description})=>_run(()=>_useCases.update(id:id,name:name,description:description)); Future<bool> updateDefaults({required String id,required List<String> defaultDays,required List<String> defaultHours,required int defaultFieldCount})=>_run(()=>_useCases.updateDefaults(id:id,defaultDays:defaultDays,defaultHours:defaultHours,defaultFieldCount:defaultFieldCount)); Future<bool> activate(String id)=>_run(()=>_useCases.activate(id)); Future<bool> close(String id)=>_run(()=>_useCases.close(id)); Future<bool> duplicate(String id,String name)=>_run(()=>_useCases.duplicate(id,name)); Future<bool> deleteOne(String id) async{_isSaving=true;notifyListeners();try{await _useCases.delete(id);_selectedIds.remove(id);await load();return true;}catch(_){_errorMessage='No se pudo eliminar la competición.';return false;}finally{_isSaving=false;notifyListeners();}} Future<BatchDeleteResult?> deleteSelected() async{if(_selectedIds.isEmpty)return null;_isSaving=true;notifyListeners();try{final r=await _useCases.deleteMany(_selectedIds.toList());_selectedIds.clear();await load();return r;}catch(_){_errorMessage='No se pudieron eliminar las competiciones.';return null;}finally{_isSaving=false;notifyListeners();}} Future<bool> _run(Future<dynamic> Function() action) async{_isSaving=true;notifyListeners();try{await action();await load();return true;}catch(_){_errorMessage='No se pudo guardar la operación.';return false;}finally{_isSaving=false;notifyListeners();}} }
